class Solution {
  public List<Long> mergeAdjacent(int[] nums) {
    long[] stack = new long[nums.length];
    int top = 0;
    for (int x : nums) {
      long cur = x;
      // a merged value may now equal its left neighbour, so keep merging
      while (top > 0 && stack[top - 1] == cur) cur += stack[--top];
      stack[top++] = cur;
    }
    List<Long> result = new ArrayList<>(top);
    for (int i = 0; i < top; i++) result.add(stack[i]);
    return result;
  }
}
